import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# packet.MoveActorAbsolute{EntityRuntimeID: 300, Flags: 0x8d, Position: mgl32.Vec3{1, 2, 3},
#   Rotation: mgl32.Vec3{270, 63.28125, 203.90625}}
GOLDEN = bytes.fromhex("ac028d0000803f0000004000004040c02d91")

# generated by gophertunnel b8bd735:
# packet.MoveActorAbsolute{EntityRuntimeID: 4294967298}
WIDE_RUNTIME_ID = bytes.fromhex("828080801000000000000000000000000000000000")

GOLDENS = [
    pytest.param(
        v2225.MoveActorAbsolutePacket(
            move_data=v2225.MoveActorAbsoluteData(
                runtime_id=300,
                header=0x8D,
                pos=v2225.Vec3(x=1.0, y=2.0, z=3.0),
                rot_x=0xC0,
                rot_y=0x2D,
                rot_y_head=0x91,
            )
        ),
        GOLDEN,
        id="full",
    ),
    pytest.param(
        v2225.MoveActorAbsolutePacket(move_data=v2225.MoveActorAbsoluteData(runtime_id=4294967298)),
        WIDE_RUNTIME_ID,
        id="wide-runtime-id",
    ),
]


@pytest.mark.parametrize("version", [v1001, v2168], ids=lambda version: version.__name__.rpartition(".")[2])
def test_move_actor_absolute_is_packet_18(version):
    assert version.PACKETS[18] is version.MoveActorAbsolutePacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_move_actor_absolute_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_move_actor_absolute_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet
